import { parse } from 'node-html-parser';

const HEADING_RE = /^h([1-6])$/i;

/**
 * Lint heading outline of an HTML document (flat document order).
 *
 * Findings (each `{ level, text, problem }`):
 *  - "no-h1":        document contains no <h1>
 *  - "multiple-h1":  more than one <h1> (reported once per extra h1)
 *  - "skipped-level": heading jumps more than one level down (e.g. h2 -> h4)
 *  - "empty-text":   heading with no text content
 *
 * @param {string} html
 * @returns {Array<{level: number, text: string, problem: string}>}
 */
export function lintHeadings(html) {
  const root = parse(html);
  const findings = [];

  const headings = root
    .querySelectorAll('h1, h2, h3, h4, h5, h6')
    .map((node) => {
      const level = Number(node.tagName.match(HEADING_RE)[1]);
      const text = node.text.trim();
      return { level, text };
    });

  let prevLevel = 0;
  let h1Count = 0;

  for (const { level, text } of headings) {
    if (level === 1) h1Count++;

    if (text === '') {
      findings.push({ level, text, problem: 'empty-text' });
      // An empty heading still advances the outline position.
      prevLevel = level;
      continue;
    }

    if (prevLevel !== 0 && level > prevLevel + 1) {
      findings.push({ level, text, problem: 'skipped-level' });
    }

    prevLevel = level;
  }

  if (h1Count === 0) {
    findings.unshift({ level: 1, text: '', problem: 'no-h1' });
  } else if (h1Count > 1) {
    // One finding per h1 beyond the first.
    let reported = 1;
    for (const { level } of headings) {
      if (level === 1 && reported > 1) {
        findings.push({ level, text: '', problem: 'multiple-h1' });
      }
      if (level === 1) reported++;
      if (reported > h1Count) break;
    }
  }

  return findings;
}

