    }

    if (prevLevel !== 0 && level > prevLevel + 1) {
      findings.push({ level, text, problem: 'skipped-level' });
    }

    prevLevel = level;
  }

  if (!sawH1) findings.unshift({ level: 1, text: '', problem: 'no-h1' });

  return findings;
}

