#!/usr/bin/env node
import { readFileSync } from 'node:fs';
import { lintHeadings } from './lint.js';

const path = process.argv[2];
if (!path) {
  console.error('usage: outline <file.html>');
  process.exit(2);
}

let html;
try {
  html = readFileSync(path, 'utf8');
} catch (err) {
  console.error(`outline: cannot read ${path}: ${err.message}`);
  process.exit(2);
}

const findings = lintHeadings(html);

for (const { level, text, problem } of findings) {
  console.log(`${level}:${problem}:${text}`);
}

process.exit(findings.length > 0 ? 1 : 0);

