import assert from 'node:assert/strict';
import { test } from 'node:test';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { fileURLToPath } from 'node:url';
import { lintHeadings } from '../src/lint.js';

const execFileAsync = promisify(execFile);
const cliPath = fileURLToPath(new URL('../src/cli.js', import.meta.url));
const fixturePath = (name) =>
  fileURLToPath(new URL(`../fixtures/${name}.html`, import.meta.url));

test('clean outline has no findings', () => {
  const html = `
    <html><body>
      <h1>Title</h1>
      <section><h2>Chapter</h2><h3>Scene</h3></section>
      <h2>Appendix</h2>
    </body></html>`;
  assert.deepEqual(lintHeadings(html), []);
});

test('skipped level is reported', () => {
  const html = `
    <html><body>
      <h1>Title</h1>
      <h2>Chapter</h2>
      <section><h4>Nested deep</h4></section>
    </body></html>`;
  assert.deepEqual(lintHeadings(html), [
    { level: 4, text: 'Nested deep', problem: 'skipped-level' },
  ]);
});

test('multiple h1s are reported once per extra h1, in order', () => {
  const html = `
    <html><body>
      <h1>First</h1>
      <h1>Second</h1>
      <p>text</p>
      <section><h1>Third</h1></section>
    </body></html>`;
  assert.deepEqual(lintHeadings(html), [
    { level: 1, text: 'Second', problem: 'multiple-h1' },
    { level: 1, text: 'Third', problem: 'multiple-h1' },
  ]);
});

test('empty heading text is reported and no-h1 when absent', () => {
  const emptyHeading = '<html><body><h1>T</h1><h3>   </h3></body></html>';
  assert.deepEqual(lintHeadings(emptyHeading), [
    { level: 3, text: '', problem: 'empty-text' },
  ]);

  const missingH1 = '<html><body><h2>A</h2><h3>B</h3></body></html>';
  assert.deepEqual(lintHeadings(missingH1), [
    { level: 1, text: '', problem: 'no-h1' },
  ]);
});

test('CLI prints findings as LEVEL:PROBLEM:TEXT and exits 1', async () => {
  await assert.rejects(
    execFileAsync(process.execPath, [cliPath, fixturePath('dupes')]),
    (err) => {
      assert.equal(err.code, 1);
      assert.equal(
        err.stdout,
        '1:multiple-h1:Second\n' +
          '1:multiple-h1:Third\n'
      );
      return true;
    }
  );
});

test('CLI exits 0 with empty stdout on a clean document', async () => {
  const { stdout } = await execFileAsync(process.execPath, [
    cliPath,
    fixturePath('clean'),
  ]);
  assert.equal(stdout, '');
});

